/* Atelier — art therapy activities, part 2: worries and stress, and more feelings */
'use strict';

THERAPY.push(
  /* ---------- worries and stress ---------- */
  { id: 'worry-dolls', th: 'worry', n: 'Worry dolls', sum: 'Tiny thread-wrapped dolls to tell a worry to at bedtime.',
    mins: 45, who: 'Ages 6 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 2,
    media: ['textile', 'mixed'],
    depth: 2,
    mat: ['Wooden dolly pegs without springs, pipe cleaners or paddle pop sticks', 'Embroidery thread or thin wool in lots of colours', 'Scraps of felt and fabric', 'PVA glue and child-safe scissors', 'Fine felt-tips or textas for faces', 'A small cloth bag, tin or box for the dolls to live in'],
    purpose: 'Worry dolls come from Guatemala, where children traditionally whisper a worry to a tiny doll and tuck it under the pillow so the doll can mind it overnight. Winding thread round and round is calm, absorbing work, and the finished doll gives a worry somewhere to rest for a while.',
    steps: ['Choose a body: a dolly peg, a pipe cleaner bent into a little figure, or a paddle pop stick.', 'Draw a simple face at the top with a fine felt-tip.', 'Dab glue just below the head, press the end of the thread into it, and wind the thread slowly round and round the body.', 'To change colour, snip the thread, glue the end down and start the next colour over it.', 'Twist a short pipe cleaner round the body for arms, or wrap a scrap of felt or fabric round it as a cloak or skirt.', 'Add wool hair or a felt hat, and glue down any loose ends.', 'Make one doll or a small family of them, and decorate a bag, tin or box for them to live in.', 'Try it out: hold a doll, tell it a worry in a whisper or just in your head, then tuck it into its bag.'],
    prompts: ['Wind slowly and watch the colours build up.', 'What would make your doll a good listener?', 'You can tell it a worry out loud, in a whisper or just in your head.', 'A doll can mind a worry overnight, and you can still talk to someone about it.'],
    adapt: ['Young children: use a wide paddle pop stick and chunky wool, with an adult starting the first wrap.', 'Older adults or limited grip: wrap wide fabric strips around a wooden spoon, which is easier to hold and turn.', 'Anyone who’d rather not make a figure can wrap a plain stick in bands of colour as a worry keeper.', 'Groups: make a basket of class worry dolls that anyone can quietly hold during a hard moment.', 'Low vision: use thick, bright wool and textured fabric, and feel each layer as it builds.'],
    reflect: ['What was it like winding the thread round and round?', 'What makes your doll a good listener?', 'Where will your doll live at home?', 'Who else could you tell a worry to?'],
    care: `Pegs, thread and pipe cleaners aren’t safe for children under 3, and scissors need supervision. Introduce worry dolls respectfully as a tradition from Guatemala, and be clear that a doll can hold a worry for the night but a trusted adult can help with it. ${CHILD_SAFE}` },
  { id: 'wait-and-see-jar', th: 'worry', n: 'Wait and see worry jar', sum: 'Sealing worries in a jar for a few weeks, then opening it to see what changed.',
    mins: 40, who: 'Ages 8 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 2,
    media: ['collage', 'words'],
    depth: 3,
    mat: ['A clean plastic jar with a lid, or a large envelope, for each person', 'Magazines, coloured paper and patterned scraps', 'Glue sticks and child-safe scissors', 'Small slips of paper and pens', 'Washi tape or stickers to seal the lid', 'A sticky label for the name and the opening date'],
    purpose: 'Worries feel huge in the moment, but many shrink, pass or turn out differently with time. Sealing a few away and opening them weeks later lets people see that for themselves, and notice how they coped with the ones that did happen.',
    steps: ['Cover a band of paper with collage, such as colours, patterns and pictures that feel steady or hopeful, and wrap it around the jar.', 'On small slips, write or draw a few everyday worries, one per slip, such as a test, a new class or a busy week at work.', 'Fold each slip, drop it into the jar and seal the lid with tape.', 'Write your name and an opening date on the label, four to six weeks away, and mark the date on a calendar.', 'Store the jars somewhere safe, such as a class cupboard or a drawer at home.', 'On opening day, read each slip quietly and sort it into piles: it passed, it shrank, it happened and I got through it, or still here.', 'For each worry that’s still here, draw or write one thing that has helped, or one person who could help now.', 'Tear up or recycle the slips you’re ready to let go of, and keep any you’d like to look at again.'],
    prompts: ['Choose worries you’d be OK to read again later.', 'Nobody else reads your slips unless you choose to show them.', 'What do you think you’ll find when you open it?', 'Which of these feels different now?'],
    adapt: ['One-to-one: use an envelope, keep it in the student’s folder and open it together in a later lesson.', 'Young children: draw worries as pictures, and open the jar after two weeks so the wait isn’t too long.', 'Adults and older adults: tuck a sealed envelope into a diary, with the opening date written on the front.', 'One-off workshops: send the jar home with the opening date and a short note on how to sort the slips.', 'Anyone who’d rather not write their worries down can seal in a coloured dot or symbol for each one.'],
    reflect: ['What did you notice when you opened your jar?', 'Which worry changed the most?', 'What helped with the worries that are still here?', 'What would you say to yourself on the day you sealed it?'],
    care: `Agree on privacy first: slips are read only by their writer unless they choose to share. Open the jars in a calm, unhurried lesson, because some worries will still be heavy or will have come true. Focus on how the person coped and who could help. ${CHILD_SAFE}` },
  { id: 'shrinking-worry', th: 'worry', n: 'Shrinking a worry', sum: 'Drawing a worry big, then smaller and smaller, until it fits in a pocket.',
    mins: 25, who: 'Ages 6 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 1,
    media: ['draw'],
    depth: 2,
    mat: ['Paper in four sizes: A3, A4, A5 and a sticky note', 'Felt-tips, textas or crayons', 'Coloured pencils for the smallest drawings', 'A small envelope (optional)'],
    purpose: 'When a worry seems to fill the whole page, drawing it again and again at smaller sizes gives a real, physical sense of cutting it down to size. Turning it into a shape or a creature keeps the details private, and the tiny final version can be tucked away or surrounded by things that help.',
    steps: ['Think of a worry that bothers you a little, not your biggest one, and imagine it as a shape, a blob or a creature.', 'Draw it big on the A3 sheet, filling the page, with a colour and texture that feel right.', 'Draw it again on the A4 sheet, a bit smaller and, if you like, a bit less fierce: softer edges, a sillier face, a calmer colour.', 'Draw it again on the A5 sheet, and notice what you leave out this time.', 'Draw it once more on the sticky note, tiny enough to cover with your thumb.', 'Around the tiny worry, draw a few things that help you feel bigger: a person, a place, a pet or a favourite thing.', 'Lay the drawings in a row from biggest to smallest, then decide where the tiny one goes: a pocket, an envelope or the recycling.'],
    prompts: ['It doesn’t have to look like the real worry. A shape or a blob is plenty.', 'What could you leave out this time?', 'How big are you compared with the worry now?', 'Notice your breathing as the drawings get smaller.'],
    adapt: ['Young children: make the worry a funny creature, and shrink it until it’s as small as an ant.', 'If drawing the same thing four times feels tedious, cut the big drawing down with scissors instead, trimming it smaller each round.', 'Low vision or limited grip: use thick markers and work from A3 down to A5 only.', 'One-to-one: the teacher shrinks a made-up worry, such as a grumpy raincloud, alongside the student.', 'Anyone who’d rather not picture a worry can shrink a scribble or a circle in a colour they choose.'],
    reflect: ['How did the worry change as it got smaller?', 'Which size felt most manageable?', 'What did you draw around the tiny worry?', 'Where did you decide to put it?'],
    care: `Suggest a small, everyday worry rather than the biggest one. If a worry still feels big however small it’s drawn, that’s fine: acknowledge it kindly and check in quietly afterwards. ${CHILD_SAFE}` },
  { id: 'scribble-calm-wash', th: 'worry', n: 'Stress scribble, calm wash', sum: 'A fast wax crayon scribble, then a slow watercolour wash over the top.',
    mins: 20, who: 'All ages · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 2,
    media: ['paint', 'draw', 'move'],
    depth: 1,
    mat: ['Thick paper or watercolour paper', 'Wax crayons or oil pastels, including white', 'Watercolours or watered-down liquid paint', 'A big soft brush and a jar of water', 'Paper towels'],
    purpose: 'Scribbling hard and fast lets tension out through the arm, and brushing a slow wash over the top helps the body settle again. Wax resists water, so the scribble shows through the wash, and the energetic marks and the calm colour end up sharing one page.',
    steps: ['Stand up and shake out your hands, arms and shoulders for a few seconds.', 'Choose a wax crayon or oil pastel and scribble hard and fast across the paper for about 30 seconds: zigzags, spikes, loops, whatever comes.', 'Add a second colour, pressing firmly so the wax goes on thickly, then stop and put the crayon down.', 'Take three slow breaths and choose a watercolour that feels calm to you.', 'Load a big brush with plenty of water and paint slow, wide strokes across the whole page, watching the scribble appear through the colour.', 'Add a second wash colour if you like, and let the colours run together.', 'Leave it to dry, then look at it from across the room.'],
    prompts: ['Press hard and go fast: there’s no wrong scribble.', 'Now slow everything down: slow breath, slow brush.', 'Watch the scribble peek through the paint.', 'Notice how your shoulders feel now.'],
    adapt: ['Secret version: scribble in white crayon on white paper, and watch it appear under the wash like magic.', 'Young children: use chunky crayons, and dab the paint on with a sponge instead of a brush.', 'Adults arriving from a busy workday: use it as a 10-minute reset before the main class activity.', 'Limited grip or mobility: tape the paper down, use a thick crayon, and do the shake-out sitting down.', 'If the scratchy sound bothers anyone, use soft oil pastels on a pad of newspaper.'],
    reflect: ['How did your body feel while scribbling, and while painting?', 'What happened when the wash went over the scribble?', 'Which part did you enjoy more: the fast part or the slow part?', 'When might a quick scribble and a slow wash help you?'] },
  { id: 'in-my-hands', th: 'worry', n: 'In my hands, out of my hands', sum: 'Sorting worries into what you can change and what you can’t.',
    mins: 35, who: 'Ages 8 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 1,
    media: ['words', 'draw', 'collage'],
    depth: 3,
    mat: ['A large sheet of paper', 'A plate and a bowl to trace two circles', 'Sticky notes or small paper shapes', 'Felt-tips, textas or coloured pencils', 'A glue stick (optional)'],
    purpose: 'Many worries are a tangle of things we can do something about and things we can’t. Sorting them onto two circles makes the difference visible, so energy can go into small actions inside the circle, and gentler kinds of coping, such as talking, resting and letting go a little, can go to the rest.',
    steps: ['Trace a small circle in the middle of the page, with a much bigger circle around it.', 'Label the inner circle “in my hands” and the outer ring “out of my hands”, or choose your own words.', 'Write or draw each worry on its own sticky note, using a word, a symbol or a tiny picture.', 'Place each note where it seems to belong, and move them around as you think.', 'If a worry has both parts, tear the note in two and put a piece in each circle.', 'In the inner circle, draw one small action beside each worry, such as packing your bag the night before or asking for help.', 'Decorate the outer ring with things that help you carry what you can’t change: a person, a comforting phrase or a calming pattern.', 'Stick the notes down if you’d like a record, or keep them loose to sort again another day.'],
    prompts: ['Is there any part of this worry you can do something about?', 'What’s one small thing in your hands this week?', 'Some things really are out of our hands. What helps you carry those?', 'You can move a note as many times as you like.'],
    adapt: ['Younger children: use two hoops or two paper plates on the table, and sort picture cards of everyday worries.', 'Adults: try it with work stress, sorting deadlines, emails and meetings, then circle one action for tomorrow.', 'Older adults: use large sticky notes and thick pens, with plenty of time to talk as the notes are placed.', 'Anyone who’d rather keep their worries private can use coloured dots that only they can read.', 'Groups: sort a set of made-up worries together first, before anyone works on their own.'],
    reflect: ['Which worries had a part you could do something about?', 'What was it like moving the notes around?', 'Which small action will you try first?', 'What helps you with the things you can’t change?'],
    care: `Some worries that are out of a person’s hands are heavy, such as illness, family problems or the news. Don’t push for details or rush to solutions, and make it clear that adult problems are not a child’s job to solve. Close with the small actions and the calming outer ring. ${CHILD_SAFE}` },
  { id: 'put-it-away', th: 'worry', n: 'Put it away for now', sum: 'Designing a strong container where worries can wait until you’re ready.',
    mins: 30, who: 'Ages 10 and up · one-to-one or small groups',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['one', 'group'],
    mess: 1,
    media: ['draw', 'mixed'],
    depth: 3,
    mat: ['A4 card or thick paper', 'Pencils, felt-tips or textas', 'Child-safe scissors', 'Sticky tape, ribbon or a paper fastener to close the door', 'Coloured pencils or oil pastels'],
    purpose: 'Some worries don’t need solving right now: they just need somewhere to wait while a person sleeps, studies or enjoys a class. Designing a strong container with a door that really closes gives them a place to be set aside for now and come back to later, ideally with support. The worries themselves never need to be drawn.',
    steps: ['Think of a container that would feel strong and safe: a treasure chest, a safe, a jar with a tight lid, a locked shed or something imaginary.', 'Draw it large on the card, adding everything that makes it strong: thick walls, a big lock, a guard animal, a secret code.', 'Cut along three sides of the door so it opens like a flap, and fold it along the fourth side. An adult can help with the cutting.', 'Decide how it closes: a tape seal, a ribbon tie, or a paper fastener and string.', 'Open the door and put the worries inside: a dot or a scribble for each, a coloured shape, or simply imagine placing them in.', 'Close the door, seal it, and decorate the outside so it looks cared for.', 'Decide where the container will be kept, and when and with whom you might open it again.', 'Finish by looking around the room and naming three things you can see.'],
    prompts: ['What would make your container really strong?', 'You don’t need to show or say what goes inside.', 'The worries are still yours. They’re just waiting for now.', 'Who might you open it with, when you’re ready?'],
    adapt: ['Anyone who finds cutting hard can draw the container and fold the whole page closed instead.', 'Younger students: make a worry-proof backpack or a treasure chest, with stickers for the lock.', 'Older adults: use a card with the flap already cut, and talk through the design rather than drawing every detail.', 'Neurodivergent or sensory-sensitive participants may prefer a real small box with a lid, covered in familiar textures.', 'One-to-one: agree with the student where the container will be kept between lessons.'],
    reflect: ['What makes your container strong?', 'How did it feel to close the door?', 'When might you use your container?', 'Who could help when it’s time to open it?'],
    care: `This is about setting worries aside for a while, not ignoring them. Never ask anyone to name or draw what goes inside, and always close with grounding. If someone seems to have a worry that can’t wait, check in privately and help them find support. ${CHILD_SAFE}` },
  { id: 'exam-butterflies', th: 'worry', n: 'Exam butterflies', sum: 'Turning a jumble of exam nerves into paper butterflies on a calm flight path.',
    mins: 60, who: 'Teens and adults · groups or one-to-one',
    ages: ['teens', 'adults'],
    fmt: ['group', 'one'],
    mess: 2,
    media: ['collage', 'words'],
    depth: 2,
    mat: ['A butterfly template, or paper to fold and cut freehand', 'Coloured paper, magazines, old maps and old worksheets', 'Scissors and glue sticks', 'A sheet of A3 card for the sky', 'Fine pens or felt-tips'],
    purpose: 'Most people feel butterflies before exams, and a little nervous energy can even sharpen focus. Writing each nerve on a paper butterfly gets the jumble out of your head, and gluing the butterflies into a calm flight path, each with something that helps, turns a scattered feeling into a plan for the day.',
    steps: ['Fold paper in half and cut out six to ten butterflies from coloured paper, magazine pages or old worksheets.', 'On the left wing of each butterfly, write or draw one exam nerve: a thought, a body feeling or a what-if, such as “mind goes blank” or “shaky hands”.', 'Scatter the butterflies across the table in a jumble, the way nerves can feel.', 'On the right wing of each one, write something that helps with that nerve, such as a slow breath, a snack, reading the question twice or starting with an easy one.', 'Draw a flight path across the card: a gentle curve, a spiral or a V like migrating birds.', 'Glue the butterflies along the path in an order that makes sense to you, such as the night before, the morning, the walk in and the first ten minutes.', 'Add a title and a few words of encouragement to yourself, then hang it where you study.'],
    prompts: ['Butterflies are normal. They often mean something matters to you.', 'What does nervous feel like for you: in your head, or in your body?', 'What has helped before, even a little?', 'The aim isn’t to get rid of the butterflies, just to help them fly in the same direction.'],
    adapt: ['One-to-one: build the flight path around the student’s actual exam timetable.', 'Adults: use it for job interviews, driving tests, presentations or university exams.', 'Anyone who’d rather not write their nerves down can use colours or small symbols on the wings.', 'Short on time: make three butterflies only, for the night before, the morning and the first ten minutes.', 'Limited grip or low vision: use pre-cut butterflies in bright colours and thick felt-tips.'],
    reflect: ['Which nerve was easiest to find a helper for?', 'How did the jumble look compared with the finished flight path?', 'Which helper will you try first?', 'Where will you put your finished piece?'],
    care: `Exam pressure can be intense, especially around the HSC. Keep the talk on what helps rather than marks or ATARs, and never compare students. If someone seems very distressed or hopeless, talk with them privately and help them reach a school counsellor or another trusted adult. ${CHILD_SAFE}` },
  { id: 'what-helps-toolkit', th: 'worry', n: 'What helps me toolkit', sum: 'A fold-out toolbox of the people, places and things that help when stress builds.',
    mins: 40, who: 'Ages 7 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 1,
    media: ['draw', 'words', 'collage'],
    depth: 2,
    mat: ['A4 card', 'Scissors and glue sticks', 'Felt-tips, textas and coloured pencils', 'Magazines for cutting out pictures (optional)', 'A sheet of helper ideas to borrow from'],
    purpose: 'When stress builds, it can be hard to remember what actually helps. Making a toolbox in a calm moment, filled with drawn tools for the body, the mind, people to talk to and places to go, gives a ready-made reminder for later, and shows people how many helpers they already have.',
    steps: ['Brainstorm together everything that helps when things feel stressful: people, places, activities, objects, sounds and words.', 'Fold the card in half like a greeting card and draw a toolbox on the front, with a handle at the top.', 'Cut around the outline through both layers, leaving part of the fold uncut so the toolbox still opens.', 'Inside, draw a tool or object for each helper and label it: headphones for music, walking shoes for a walk, a phone for calling a friend.', 'Aim for a mix: something for your body, something for your mind, someone to talk to and somewhere to go.', 'Add a tool for words, with a short phrase you could say to yourself, such as “one thing at a time”.', 'Decorate the outside, write your name on the handle, and put a star next to one tool to try this week.', 'Keep the toolbox somewhere easy to find, such as a school bag, a bedside drawer or the fridge door.'],
    prompts: ['What helps you, even a tiny bit, when things feel hard?', 'Who is someone you could talk to?', 'Small things count, like a glass of water or a cuddle with the dog.', 'Which tools could you use at school or work, and which at home?'],
    adapt: ['Young children: choose from picture cards of helpers to glue in, with an adult writing the labels.', 'Teens: make a phone-sized version, or photograph the toolbox to keep on their phone.', 'Adults: make a work version for the desk drawer, with tools for between meetings and for the trip home.', 'Older adults and aged care: make a large-print version with photos of family, pets and favourite places.', 'If the toolbox shape feels fiddly, use a folded card or an envelope of separate tool cards.'],
    reflect: ['Which tool do you already use without thinking about it?', 'Was anything hard to think of?', 'Which tool will you try this week?', 'Where will you keep your toolbox?'],
    care: `Some people struggle to name anyone they can talk to. Keep the brainstorm broad, including teachers, coaches, neighbours, pets and support services, so nobody feels left out, and quietly note anyone who seems to have no one. ${CHILD_SAFE}` },
  { id: 'trace-breathe-card', th: 'worry', n: 'Trace and breathe card', sum: 'A pocket card with a raised line to trace with a finger while breathing slowly.',
    mins: 35, who: 'Ages 5 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 2,
    media: ['mixed', 'draw'],
    depth: 1,
    mat: ['Pocket-sized pieces of card, about 9 cm by 13 cm', 'Pencils, scrap paper, and coloured pencils or felt-tips', 'PVA glue in a squeeze bottle', 'Fine sand, salt or coloured sand', 'Wool or string as an alternative to sand', 'A tray to catch the extra sand'],
    purpose: 'Slow breathing is easier with something to follow. Tracing a raised line with a fingertip, breathing in on the way up and out on the way down, gives the hands, eyes and breath one calm job to share, and the card is small enough to carry to school, work or an appointment.',
    steps: ['Choose a breathing shape: a row of hills, a five-pointed star, a wave or a sideways figure eight.', 'Try it on scrap paper first, tracing up the line while breathing in and down while breathing out, and adjust the size until it feels comfortable.', 'Draw the shape in pencil on the card, large enough to trace with a fingertip.', 'Colour the background around it with soft patterns or colours you find calming.', 'Squeeze a thin, steady line of PVA glue along the pencil line, or press a length of wool into a line of glue.', 'Sprinkle sand over the wet glue, tip the extra onto the tray, and leave the card to dry flat overnight.', 'On the back, write a reminder of how to use it, such as “up, breathe in; down, breathe out”.', 'Once it’s dry, trace the raised line slowly with a finger for three or four rounds.'],
    prompts: ['Up the hill, breathe in. Down the hill, breathe out.', 'Let your finger move as slowly as your breath.', 'You could use it anywhere: on the bus, in class or in a waiting room.', 'Make the shape a size that feels comfortable for your finger.'],
    adapt: ['Young children: use a big wave on larger card, with a thick glue line and coloured sand.', 'Low vision: make the raised line bold and thick, and add a bump of glue to mark the starting point.', 'Older adults or limited grip: use pre-drawn shapes, and press wool into glue rather than squeezing a bottle.', 'Sensory-sensitive participants: use smooth wool instead of sand, or a line of puffy paint.', 'Anyone who finds focusing on the breath uncomfortable can trace the shape slowly while counting instead.'],
    reflect: ['Which shape did you choose, and why?', 'How did tracing and breathing together feel?', 'Did your breathing change after a few rounds?', 'Where could you keep your card?'],
    care: 'Keep breathing slow and natural, never forced: anyone who feels dizzy or uncomfortable can stop and simply trace. Keep sand away from eyes, and keep sand, salt and wool away from children under 3.' },
  { id: 'brave-ladder', th: 'worry', n: 'Brave ladder', sum: 'A ladder of small, brave steps towards something that feels scary.',
    mins: 35, who: 'Ages 6 and up · one-to-one or small groups',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['one', 'group'],
    mess: 1,
    media: ['draw', 'words'],
    depth: 3,
    mat: ['A long strip of card, about 10 cm by 40 cm', 'A ruler and a pencil', 'Felt-tips, textas or coloured pencils', 'Sticky notes for planning the steps', 'Star stickers or a stamp'],
    purpose: 'Facing something scary all at once can feel impossible, but one small step at a time is often doable. Drawing a ladder with the easiest step at the bottom and the goal at the top turns a big fear into a plan, and colouring in each rung as it’s climbed makes progress easy to see.',
    steps: ['Choose a goal that feels a bit scary but worth working towards, such as joining in at lunch, ordering at a café or speaking up in a meeting.', 'Draw a ladder up the strip of card with six to eight rungs.', 'Draw or write the goal at the top, with a picture of how it might feel to get there.', 'On sticky notes, brainstorm smaller steps, from a little bit brave to very brave.', 'Put the notes in order with the easiest at the bottom, then copy them onto the rungs.', 'Beside the ladder, add helpers: people who could come with you, something to hold, or words to say to yourself.', 'Choose the bottom rung to try this week, and colour it in or add a star once it’s done.', 'Bring the ladder back to class to celebrate each rung climbed, at whatever pace feels right.'],
    prompts: ['What’s a step that feels only a little bit brave?', 'You can stay on a rung for as long as you need.', 'Who or what could help you on this step?', 'Every rung counts, even the bottom one.'],
    adapt: ['Young children: four big rungs with pictures, and an adult helps break the goal into steps.', 'Adults: try it for work fears, such as speaking up in meetings or making a difficult phone call.', 'Older adults: use it for goals like joining a new group, trying a new bus route or video-calling family.', 'Anyone who prefers can draw stairs, stepping stones or a mountain path instead of a ladder.', 'Neurodivergent participants: keep each step concrete and specific, with a small picture for each.'],
    reflect: ['Which rung feels easiest to start with?', 'What helps you feel brave?', 'How will you celebrate when you climb a rung?', 'What did you notice once the steps were in order?'],
    care: `Let each person choose their own goal and pace, and never push anyone up a rung. Keep it to everyday fears. If a fear is stopping someone from going to school or work, or from seeing people, gently suggest they talk with a GP or a school counsellor. ${CHILD_SAFE}` },
  { id: 'squishy-stress-balls', th: 'worry', n: 'Squishy stress balls', sum: 'Balloons filled with flour or rice and decorated as squeezable characters.',
    mins: 30, who: 'Ages 8 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 3,
    media: ['mixed'],
    depth: 1,
    mat: ['Latex-free balloons, two per ball', 'Plain flour, or uncooked rice', 'A small funnel, a spoon and a pencil', 'Permanent markers', 'Scissors for an adult to use', 'A tray, a damp cloth, and a dustpan and brush'],
    purpose: 'Squeezing something soft gives restless hands and tense muscles somewhere to go, and many people find it calming at a desk, in a waiting room or before a test. Making the ball yourself, and giving it a face, turns it into a friendly, personal tool rather than another thing to buy.',
    steps: ['Cover the table and work over a tray, because flour gets everywhere.', 'Stretch the first balloon a few times with your hands to soften it.', 'Fit the neck of the balloon over the funnel and spoon in the filling a little at a time, nudging it through with a pencil, until the balloon is about the size of a tennis ball.', 'Squeeze out the air, then tie a tight knot close to the filling, with an adult’s help if needed.', 'An adult snips the neck off a second balloon, which is then stretched over the first to cover the knot and make the ball stronger.', 'Draw a face, a creature or a pattern on it with permanent marker.', 'Try it out: squeeze slowly as you breathe in, and let go as you breathe out.'],
    prompts: ['Gently does it: squeeze slowly, then let go.', 'Squeeze as you breathe in, and let go as you breathe out.', 'Rice feels crunchy and flour feels smooth. Which do you like?', 'Who is your stress ball? Give it a name.'],
    adapt: ['Squish pot: fill a small lidded tub with homemade playdough and decorate the lid, which avoids balloons altogether.', 'Sensory-sensitive participants: feel sample fillings in sealed snap-lock bags first, to choose the texture they like.', 'Older adults or sore hands: fill the ball loosely so it’s extra soft, and squeeze gently, stopping if anything hurts.', 'Limited grip: a partner holds the funnel while the person spoons in the filling.', 'Groups: the teacher runs one filling station while everyone else decorates at their tables.'],
    reflect: ['Which filling did you choose, and how does it feel?', 'How did your hands feel after a few slow squeezes?', 'When and where might you use your stress ball?'],
    care: 'Check for latex, wheat and gluten allergies first, and use latex-free balloons, or rice instead of flour, where needed. Uninflated or burst balloons are a choking hazard, especially for children under 8, so supervise closely, keep balloons out of mouths and collect every scrap. Avoid stirring up flour dust.' },
  { id: 'worry-to-wonder', th: 'worry', n: 'Worry to wonder', sum: 'Lift-the-flap drawings that turn a “what if” worry into an “I wonder” question.',
    mins: 20, who: 'Ages 7 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 1,
    media: ['words', 'draw'],
    depth: 2,
    mat: ['A4 paper', 'Child-safe scissors', 'Felt-tips, textas or coloured pencils', 'A list of “I wonder” sentence starters'],
    purpose: '“What if” worries tend to imagine the worst, but the same unknown can also be met with curiosity. Drawing a worry on the front of a flap and an “I wonder” question underneath is a playful way to look at something new or uncertain from both sides, without pretending the worry isn’t real.',
    steps: ['Fold the paper in half lengthways, then cut the top layer into three or four flaps, stopping at the fold.', 'Think of something new or uncertain coming up, such as a new school, a trip, a first exhibition or retiring from work.', 'On the front of the first flap, write and draw a “what if” worry about it, such as “what if nobody talks to me”.', 'Lift the flap and, underneath, turn it into an “I wonder” question about the same thing, such as “I wonder who I’ll meet”, with a drawing to match.', 'Fill the other flaps the same way, with different worries or different sides of the same one.', 'Decorate the cover and give the booklet a title.', 'Read it through from start to finish, lifting each flap to go from worry to wonder.'],
    prompts: ['What’s the “what if” your mind keeps asking?', 'What might you be curious about, as well as worried?', 'The worry stays on the flap. The wonder is just another way of looking.', 'You can be worried and curious at the same time.'],
    adapt: ['Young children: make one big flap together about something new but fun, like a first sleepover or a new pet.', 'Older adults: use it for things like a new class, a trip or a new phone, with larger paper and thick pens.', 'Anyone who doesn’t want to draw can write the words only, or use pictures from magazines.', 'Groups: brainstorm wonder starters together first, such as “I wonder what”, “I wonder who” and “I wonder how”.', 'Neurodivergent participants: offer ready-made worry and wonder pairs to choose from and change.'],
    reflect: ['Which flap was easiest to turn around?', 'How did it feel to lift the flap and read the wonder?', 'Was there a worry that was hard to turn into a wonder?', 'Which “I wonder” question would you like to find out about?'],
    care: `This works best for everyday uncertainty. If a worry is about something frightening or unsafe, don’t try to turn it into a wonder: listen, acknowledge it and check in afterwards. ${CHILD_SAFE}` },

  /* ---------- more feelings ---------- */
  { id: 'feelings-face-sticks', th: 'feel', n: 'Feelings face sticks', sum: 'Cut-paper feelings faces on paddle pop sticks, for check-ins and play.',
    mins: 30, who: 'Ages 5 to 11 · groups or one-to-one',
    ages: ['kids'],
    fmt: ['group', 'one'],
    mess: 2,
    media: ['collage', 'draw'],
    depth: 1,
    mat: ['Card circles about 10 cm across, or small paper plates', 'Paddle pop sticks', 'Coloured paper scraps for eyebrows, eyes and mouths', 'Glue sticks, sticky tape and child-safe scissors', 'Felt-tips, textas or crayons', 'A small unbreakable mirror (optional)'],
    purpose: 'Making faces from loose paper eyebrows, eyes and mouths shows children how much a face can say, and gives them a simple way to show a feeling without having to find the words. The finished sticks can be held up at check-in time, used for puppet play, or kept in a cup for days when talking is hard.',
    steps: ['Talk about a few feelings together, such as happy, sad, cross, worried, surprised and calm, and try pulling each face in a mirror.', 'Cut eyebrows, eyes and mouths from paper scraps: straight, curved, wiggly, thick and thin.', 'Before gluing, move the pieces around on a card circle and notice how tilting an eyebrow or turning a mouth changes the feeling.', 'When a face looks right, glue the pieces down and add details with felt-tips, such as cheeks, freckles or tears.', 'Tape a paddle pop stick firmly to the back of each face.', 'Make four to six faces, and write the feeling word on the back of each, or leave it blank to decide later.', 'Try them out: the teacher names a moment, such as losing a game or a birthday party, and everyone holds up a face it might bring.', 'Keep the sticks in a cup to use at the start or end of class.'],
    prompts: ['What happens to the face if the eyebrows tip down in the middle?', 'Can a face show two feelings at once?', 'Different people can feel different things about the same moment.', 'Which face shows how you feel right now? You can keep it to yourself if you like.'],
    adapt: ['Very young children: start with three faces, such as happy, sad and cross, using pre-cut features.', 'Limited grip: use large pre-cut pieces, and stick the faces onto paper plates for a bigger handle.', 'Neurodivergent children: put photos of real faces alongside, and keep the feeling words on the back to help with matching.', 'Groups: make a class set for daily check-ins, with each child adding one face.', 'Children who don’t want to make faces can choose a colour or a shape for each feeling instead.'],
    reflect: ['Which part of the face changed the feeling the most?', 'Which face was hardest to make?', 'Did anyone choose a different face from you for the same moment?', 'When might you use your sticks?'],
    care: `Check-ins are an invitation, never a test: a child can hold up any face, or none, and doesn’t have to explain it. Keep sticks and small paper pieces away from children under 3, and supervise scissors. If a child often holds up a sad or scared face, check in quietly. ${CHILD_SAFE}` },
  { id: 'anger-volcano', th: 'feel', n: 'Anger volcano', sum: 'Building a playdough volcano and making it erupt, to talk about anger safely.',
    mins: 45, who: 'Ages 5 to 12 · groups or one-to-one',
    ages: ['kids', 'teens'],
    fmt: ['group', 'one'],
    mess: 3,
    media: ['mixed', 'clay', 'paint'],
    depth: 2,
    mat: ['A small plastic cup and a large tray for each volcano', 'Playdough in browns, greys and greens', 'Bicarb soda and white vinegar', 'Dishwashing liquid and red or orange food colouring', 'Safety glasses or swimming goggles', 'Paper, crayons and a teaspoon'],
    purpose: 'Anger often builds slowly, like pressure inside a volcano, before it bursts out. Building a volcano and watching a safe, fizzy eruption gives children a vivid picture of that build-up, and a playful way to talk about the early rumbles they notice and what helps them cool down before the lava flows.',
    steps: ['Stand the cup in the middle of the tray and build a playdough mountain around it, leaving the top of the cup open as the crater.', 'While you build, talk about what anger can feel like as it grows: hot cheeks, tight fists, a loud voice, a thumping heart.', 'Press small playdough rocks around the base, one for each early sign that anger is building.', 'Put on safety glasses. Spoon two teaspoons of bicarb soda into the crater, with a squirt of dishwashing liquid and a few drops of colouring.', 'Pour in a little vinegar all at once, stand back and watch the eruption.', 'While it bubbles, take slow breaths together, and notice how the eruption slows down and settles.', 'Refill the crater and try a gentler eruption, adding the vinegar a spoonful at a time, and compare the two.', 'On paper, draw what helps you cool down before the lava flows, such as a breath, a run, a cuddle, a quiet corner or a drink of water.'],
    prompts: ['Everyone feels angry sometimes. The feeling is OK; it’s what we do with it that matters.', 'What are your early rumbles, the first signs that anger is building?', 'What happens when we add the vinegar slowly instead of all at once?', 'What helps your volcano cool down?'],
    adapt: ['Paint version: blow runny red and orange paint up a drawn volcano with a straw, or flick it with an old toothbrush, for an eruption without the fizz.', 'Sensory-sensitive children: make a smaller eruption, give a countdown before it fizzes, and offer gloves for the playdough.', 'Older children and young teens: draw a cut-away volcano labelled with the build-up, the rumbles, the eruption and the cooling down.', 'Limited grip: build around a wider cup with ready-rolled playdough, and pour the vinegar from a squeeze bottle.', 'One-to-one: build the volcano together and keep the drawing of what helps as a reminder.'],
    reflect: ['What did you notice when the vinegar went in?', 'What are your early signs that anger is building?', 'What was different about the slow eruption?', 'What helps you cool down?'],
    care: `Supervise closely and wear eye protection: vinegar stings if it splashes, so rinse eyes with water if it does. Check allergies to food colouring and playdough ingredients, and never seal the container. Keep talk on what anger feels like and what helps, not on who makes a child angry. ${CHILD_SAFE}` },
  { id: 'feelings-thermometer', th: 'feel', n: 'Feelings thermometer', sum: 'A colour scale from tiny to huge feelings, with a slider to show today’s size.',
    mins: 35, who: 'Ages 6 to 15 · groups or one-to-one',
    ages: ['kids', 'teens'],
    fmt: ['group', 'one'],
    mess: 2,
    media: ['paint', 'words'],
    depth: 2,
    mat: ['A strip of thick card, about 8 cm by 30 cm', 'Poster paint or watercolours', 'Brushes and a jar of water', 'A pencil and a ruler', 'A large paper clip or a clothes peg for the slider', 'Fine felt-tips for labels'],
    purpose: 'Feelings come in sizes, and noticing how big a feeling is can be the first step to knowing what might help. Painting a thermometer in bands of your own chosen colours, from tiny to huge, and labelling each level with what it feels like and what helps, gives a simple way to say “I’m at a four” without needing many words.',
    steps: ['Choose one feeling to measure, such as worried, cross or excited, or make a general scale for how big any feeling is.', 'Draw a thermometer on the card with a round bulb at the bottom, and mark five levels up the tube.', 'Choose your own colour for each level, from tiny at the bottom to huge at the top, and paint the bands, letting them blend where they meet if you like.', 'While it dries, think about what each level looks and feels like for you, from a one all the way up to a five.', 'Next to each band, write or draw a clue, such as a face, a body feeling or a word.', 'On the other side of the tube, add one thing that helps at each level, such as a sip of water, a break, a hug or a quiet space.', 'Clip the paper clip or peg onto the side, and slide it to show how big the feeling is today.'],
    prompts: ['You choose the colours: there’s no right colour for a feeling.', 'What does a tiny worry feel like? What about a huge one?', 'What helps when you’re at a two? What about a four?', 'Where’s your slider today? You can keep it to yourself if you like.'],
    adapt: ['Young children: three levels only, small, medium and big, with faces instead of words.', 'Teens: use a scale from one to ten, and add what other people might notice at each level.', 'Limited grip: paint the bands with sponges or chunky brushes, and use a large peg as the slider.', 'Low vision: choose strongly contrasting colours, and add a raised dot of glue at each level.', 'Groups: use the sliders for a quiet check-in at the start of class, shown only to the teacher if preferred.'],
    reflect: ['How did you choose your colours?', 'Which level was hardest to describe?', 'What helps you move down the thermometer?', 'Where might you keep your thermometer?'],
    care: `Be clear that the colours are each person’s own choice, and never read meaning into them. Sliders can stay private. If a student often sits near the top of the scale, check in with them quietly. ${CHILD_SAFE}` },
  { id: 'feelings-monsters', th: 'feel', n: 'Feelings monsters', sum: 'Modelling a little monster for each feeling, with its own name and needs.',
    mins: 60, who: 'Ages 5 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 3,
    media: ['clay', 'collage'],
    depth: 1,
    mat: ['Air-dry clay or playdough', 'Pencils, forks and paddle pop sticks for texture', 'Googly eyes, pipe cleaners, feathers and paper scraps', 'Small cards and felt-tips', 'Damp cloths and a board or placemat to work on'],
    purpose: 'Turning a feeling into a funny little monster gives it a shape, a name and some distance, which makes it easier to talk about. Squashing, pinching and rolling clay is satisfying in itself, and deciding what each monster needs helps people think about what helps them, too.',
    steps: ['Choose a feeling you know well, such as grumpy, jittery, excited, bored or calm.', 'Warm a lump of clay in your hands and think about the feeling’s shape: spiky, droopy, round, wobbly or stretched.', 'Model a monster with that feeling, pinching out spikes, rolling arms and legs, and pressing in textures with a pencil or fork.', 'Add features from the scraps: googly eyes, pipe-cleaner antennae, feathers or paper teeth.', 'Give the monster a name, such as the Grumbles or Jitterbug, and decide how it moves and what it sounds like.', 'On a small card, write or draw what makes your monster grow and what helps it settle.', 'Make a second monster for a different feeling, and introduce the two to each other.', 'Set the monsters out like a gallery, or take them home with their cards. Air-dry clay monsters can be painted next lesson.'],
    prompts: ['If this feeling were a monster, what shape would it be?', 'How does your monster move: stomp, wobble, zoom or tiptoe?', 'What does your monster need when it gets big?', 'All feelings are welcome here, even the grumpy ones.'],
    adapt: ['Young children: use playdough, and choose from a few feelings on picture cards, such as happy, sad, cross and scared.', 'Teens: make a monster for a feeling that often gets in the way, such as stress before a deadline, and give it a ridiculous name.', 'Older adults: call them feeling characters, and use soft clay warmed in the hands first.', 'Anyone who doesn’t like the feel of clay can wear thin gloves, or draw or collage their monster instead.', 'Groups: build a monster family on one table, with each person adding a different feeling.'],
    reflect: ['What shape did your feeling become?', 'What did you decide your monster needs?', 'How did it feel to give the feeling a name?', 'Which monster would you like to visit more often?'],
    care: 'Keep googly eyes, feathers and other small pieces away from children under 3, and check for wheat allergies if using homemade playdough. Let people choose any feeling, comfortable or not, and never interpret the monsters.' },
  { id: 'feelings-comic', th: 'feel', n: 'Feelings comic strip', sum: 'A four-panel comic about a character whose feeling arrives, grows and changes.',
    mins: 40, who: 'Ages 8 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 1,
    media: ['draw', 'words'],
    depth: 2,
    mat: ['Paper ruled into four large panels', 'Pencils and an eraser', 'Fine black pens', 'Coloured pencils or textas', 'A sheet of simple faces and speech bubble shapes for ideas'],
    purpose: 'Telling a feeling’s story through a made-up character gives a little distance, so it’s easier to look at how a feeling starts, how it shows in the face and body, and what helps it change. Comics suit people who think in pictures, and stick figures work perfectly.',
    steps: ['Invent a character: an animal, a robot, a blob, a person or anything at all.', 'Choose a feeling for the story, such as nervous, jealous, proud, embarrassed or cross.', 'Panel 1: show the character before the feeling arrives, doing something ordinary.', 'Panel 2: show what happens and the feeling arriving, using the face, the body and lines around the character, such as zigzags, sweat drops or steam.', 'Panel 3: show the feeling at its biggest, with a thought bubble for what the character is thinking.', 'Panel 4: show what helps, such as a friend, a breath, a joke, a snack or some time, and how the character feels now.', 'Add speech bubbles, sound effects and colour, and give the comic a title.', 'If you like, swap comics with someone and tell them one thing you noticed about how their character’s feeling changed.'],
    prompts: ['Stick figures are perfect for comics.', 'How could you show that feeling without words: eyebrows, shoulders, wobbly lines?', 'What does your character think but not say?', 'What helps the feeling change, even a little?'],
    adapt: ['Young children: three big panels, for before, during and after, with no words needed.', 'One-to-one: the teacher draws panel 1 and the student continues, or they take turns, a panel each.', 'Older adults: use large panels, and offer printed characters to colour, cut out and glue.', 'Anyone who doesn’t want to draw can use cut-out magazine figures, or write the words while a partner draws.', 'Neurodivergent participants may like to plan the panels on sticky notes first, or base the strip on an everyday moment, such as a change of plan.'],
    reflect: ['How did you show the feeling in your drawing?', 'What helped your character in the last panel?', 'Was any panel harder to draw than the others?', 'Which helper might you borrow from your character?'],
    care: `An invented character keeps some distance, so don’t push anyone to make the story about themselves. If a comic shows something worrying, such as someone being hurt, respond calmly and privately. ${CHILD_SAFE}` },
  { id: 'mood-mandala-week', th: 'feel', n: 'Week of moods mandala', sum: 'Stamping one ring a day for a week to make a mandala of changing moods.',
    mins: 15, who: 'Ages 7 and up · one-to-one or groups',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['one', 'group'],
    mess: 2,
    media: ['print', 'draw'],
    depth: 2,
    mat: ['Thick paper with seven circles drawn one inside another', 'Washable ink pads, or paint on a damp sponge, in several colours', 'Small stamps: bottle tops, cotton buds, erasers, corks and cut sponge shapes', 'A fine pen', 'A plastic sleeve or folder to carry it home'],
    purpose: 'Moods change from day to day, and seeing that can be reassuring, especially on a hard day. Stamping one ring of a mandala each day, in colours and shapes chosen for that day’s mood, makes a quick, gentle daily ritual, and after a week the finished circle shows the whole mix at a glance, without needing a single word.',
    steps: ['Draw seven circles one inside another, or use a printed template, with a small circle in the centre for the first day.', 'Set out the ink pads and stamps, and test each stamp on scrap paper.', 'Take a moment to notice your mood today: how your body feels, how much energy you have, what kind of day it has been.', 'Choose a colour and a stamp that suit today’s mood, and stamp around the centre circle. Your choices only need to make sense to you.', 'Write the day lightly beside the ring, or keep a tiny key on the back if you like.', 'Each day for the next six days, stamp the next ring out in the same way. It only takes a few minutes.', 'At the end of the week, look at the whole mandala and notice the mix of rings, without judging any day.', 'Bring it to class to talk about if you’d like to, or simply start a new one.'],
    prompts: ['There’s no right colour for a mood. Choose whatever feels right today.', 'Would today’s ring be busy or spacious, bold or soft?', 'Every day gets a ring, even the hard ones.', 'What do you notice when you look at the whole week?'],
    adapt: ['Pencil version: use coloured pencils or felt-tips instead of stamps, for a mess-free kit at home.', 'Holiday workshops: stamp a ring first thing each morning, Monday to Friday, for a five-ring mandala.', 'Young children: use big stamps and five rings, and do the day’s ring together at home or in class.', 'Limited grip: use chunky stamps, such as cotton reels or sponge shapes with handles, on a larger sheet.', 'Low vision: use bold, high-contrast colours on a large sheet, with the rings drawn in thick marker.'],
    reflect: ['What did you notice when you looked at the whole week?', 'Which ring was easiest to choose for, and which was hardest?', 'How did it feel to make a ring on a hard day?', 'Would you like to keep going for another week?'],
    care: `Keep the mandala private unless the person chooses to share it, and never interpret their colours or shapes. If someone mentions a hard week, or several, check in kindly and help them find support if needed. ${CHILD_SAFE}` },
  { id: 'two-feelings-fold', th: 'feel', n: 'Two feelings at once', sum: 'Folding two paint colours together to see two feelings meet in the middle.',
    mins: 25, who: 'Ages 6 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 2,
    media: ['paint', 'print'],
    depth: 3,
    mat: ['A4 paper or thin card, folded in half and opened out', 'Runny washable poster paint in squeeze bottles, or pots with spoons', 'Newspaper and paper towels', 'Felt-tips or oil pastels for adding details once dry'],
    purpose: 'Feeling two things at once, like excited and nervous before camp or happy and sad at the end of a school year, is completely normal but can be confusing. Putting a colour for each feeling on either side of a fold and pressing them together shows them meeting and mixing in the middle, which can make mixed feelings easier to notice and talk about.',
    steps: ['Think of a time when you felt two things at once, such as excited and nervous, or proud and a bit sad. Everyday moments work well.', 'Choose a colour for each feeling. Your colours only need to make sense to you.', 'Open the folded paper, then drop or drizzle the first colour on the left side, close to the fold, and the second colour on the right.', 'Fold the paper closed and press firmly, smoothing outwards from the fold with your hand.', 'Open it slowly and look at where the two colours met and mixed.', 'Try again with different amounts of each colour, for times when one feeling was bigger than the other.', 'Once dry, add a word or a small drawing to each side, and a word for the mixed part in the middle if one comes to mind.'],
    prompts: ['Can you feel two things at once? Most people do, often.', 'Was one feeling bigger? You could use more of that colour.', 'Look at the middle: what happened where they met?', 'Both feelings are allowed to be there.'],
    adapt: ['Young children: start with a fun pair, like excited and wobbly before a birthday party, and use two big blobs of paint.', 'Older adults: use larger card and squeeze bottles, and talk about pairs like proud and tired, or relieved and a bit flat.', 'Anyone who dislikes wet paint can colour each side in oil pastel and blend the middle with a tissue.', 'Limited grip: use squeeze bottles, and press the fold with a rolling pin or the side of the hand.', 'Groups: lay the prints side by side and notice how different everyone’s meeting places look.'],
    reflect: ['What happened where the two colours met?', 'Was one feeling bigger than the other?', 'What was it like to put two different feelings on one page?', 'When else might you feel two things at once?'],
    care: `Mixed feelings often come with big changes, such as separations, moves or illness. Let people choose everyday moments if they prefer, don’t probe, and never read meaning into the colours. ${CHILD_SAFE}` }
);
